module five_bit_rca(
    input [4:0] A,
    input [4:0] B,
    input Cin,
    output [4:0] S,
    output Cout
);

    // C is a 4-bit wire used to shuttle the carry-out.
    // Signal generated by one full adder stage to the carry-in of the very next stage.
    wire [3:0] C;
    
    // Adds the LSBs (A[0], B[0]) and the initial carry-in (Cin).
    full_adder FA0 (.A(A[0]), .B(B[0]), .Cin(Cin), .S(S[0]), .Cout(C[0]));

    // FA1: Adds bit 1, taking Carry-out C[0] as carry-in.
    full_adder FA1 (.A(A[1]), .B(B[1]), .Cin(C[0]), .S(S[1]), .Cout(C[1]));

    // FA2: Adds bit 2, taking carry-out C[1] as carry-in.
    full_adder FA2 (.A(A[2]), .B(B[2]), .Cin(C[1]), .S(S[2]), .Cout(C[2]));

    // FA3: Adds bit 3, taking carry-out C[2] as carry-in.
    full_adder FA3 (.A(A[3]), .B(B[3]), .Cin(C[2]), .S(S[3]), .Cout(C[3]));

    // FA4: Adds the MSBs (A[4], B[4]), taking carry-out C[3] as carry-in.
    full_adder FA4 (.A(A[4]), .B(B[4]), .Cin(C[3]), .S(S[4]), .Cout(Cout));
endmodule